<?php require_once dirname(__DIR__) . '/header.php'; ?><?php require_once __DIR__.'/../header.php';?><main class="page"><section class="hero"><h1>Random Number Generator</h1><p class="muted">Generate random numbers between any minimum and maximum value.</p></section><div class="layout"><section class="tool"><div class="row"><div><label><strong>Minimum</strong></label><input class="input" id="min" type="number" value="1"></div><div><label><strong>Maximum</strong></label><input class="input" id="max" type="number" value="100"></div></div><label><strong>How many numbers?</strong></label><input class="input" id="count" type="number" min="1" max="1000" value="1"><button class="btn" onclick="generate()">Generate Numbers</button><button class="btn" onclick="copyAll()">Copy All</button><div class="out" id="out">Your random numbers will appear here.</div></section><aside class="tools"><h3>🛠️ All Tools</h3><?php $items=['image-compressor.php'=>'🖼️ Image Compressor','png-to-jpg.php'=>'↩️ PNG to JPG','jpg-to-webp.php'=>'🖼️ JPG to WebP','png-to-webp.php'=>'🖼️ PNG to WebP','gif-maker.php'=>'🎞️ GIF Maker','pdf-to-jpg.php'=>'📄 PDF to JPG','pdf-to-png.php'=>'📄 PDF to PNG','pdf-merger.php'=>'📑 PDF Merger','pdf-splitter.php'=>'📄 PDF Splitter','pdf-compressor.php'=>'📦 PDF Compressor','qr-generator.php'=>'🔐 QR Code Generator','age-calculator.php'=>'🎂 Age Calculator','percentage-calculator.php'=>'% Percentage Calculator','bmi-calculator.php'=>'⚖️ BMI Calculator','unit-converter.php'=>'📏 Unit Converter','stopwatch-timer.php'=>'⏱️ Stopwatch Timer','lorem-ipsum-generator.php'=>'📄 Lorem Ipsum','unix-timestamp.php'=>'🕐 Unix Timestamp','timestamp-converter.php'=>'🕐 Timestamp Converter','uuid-generator.php'=>'🆔 UUID Generator','random-number-generator.php'=>'🎲 Random Number Generator','json-formatter.php'=>'{} JSON Formatter','word-counter.php'=>'📝 Word Counter','case-converter.php'=>'🔤 Case Converter','url-encoder.php'=>'🔗 URL Encoder'];foreach($items as $f=>$n):?><a class="<?=basename($_SERVER['SCRIPT_NAME'])===$f?'active':''?>" href="/tools/<?=htmlspecialchars($f,ENT_QUOTES,'UTF-8')?>"><?=htmlspecialchars($n)?></a><?php endforeach;?><a href="/tool.php">View All Tools →</a></aside></div></main><?php require_once __DIR__.'/../footer.php';?><script>let values=[];function generate(){let a=Number(document.getElementById('min').value),b=Number(document.getElementById('max').value),n=Math.min(1000,Math.max(1,parseInt(document.getElementById('count').value)||1));if(!Number.isFinite(a)||!Number.isFinite(b)||a>b){document.getElementById('out').textContent='Enter a valid minimum and maximum.';return}values=Array.from({length:n},()=>Math.floor(Math.random()*(b-a+1))+a);document.getElementById('out').textContent=values.join('\n')}async function copyAll(){if(!values.length)generate();await navigator.clipboard.writeText(values.join('\n'))}</script></body></html>